using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.Networking;
using CatCafePreview.Standalone;
namespace CatCafePreview {
 public sealed class StandaloneCocoConversationSmoke:MonoBehaviour {
  static int checks;static void Check(bool ok,string label){checks++;if(!ok)throw new Exception("Coco ADV: "+label);}
  public static CafeRules Rules(){var r=JsonUtility.FromJson<CafeRules>(Resources.Load<TextAsset>("CatCafeStandalone/rules").text);r.intake.day=r.regular_introduction.day=9999;r.growth.threshold=10000;r.starting_funds=20000;r.store_events.probability=0;r.goal_stages[0].target=101;r.goal_stages[0].days=30;r.max_probability=r.stress_per_service_tick=r.fatigue_per_service_tick=0;return r;}
  static CafeResponse Send(LocalCafeBackend b,string kind,string choice=null,int slot=1){var s=b.Simulation.State;CafeResponse r=null;var it=b.Request("/commands",JsonUtility.ToJson(new PythonShiftCommand{request_id=Guid.NewGuid().ToString("N"),instance_id=s.instance_id,expected_revision=s.revision,kind=kind,choice=choice,cat_id="visiting-cat-1",save_slot=slot,save_id=slot.ToString(),working_cats=new string[0]}),v=>r=v);while(it.MoveNext()){}return r;}
  static void Good(LocalCafeBackend b,string kind,string choice=null,int slot=1){var r=Send(b,kind,choice,slot);Check(r.result==UnityWebRequest.Result.Success,kind+": "+r.error);}
  static string Facts(LocalCafeBackend b)=>CafeReplayJournal.Digest(b.Simulation.State);
  static void Finish(LocalCafeBackend b){var r=b.CocoConversation;r.progress.node=CafeCocoDialogue.Lines(r,r.progress.branch_id).Length;r.progress.page_offset=0;CafeCocoDialogue.Finish(r);b.RememberViewedConversations();}
  public static void Setup(LocalCafeBackend b){b.Simulation.Restore(new CafeSimulation(b.Simulation.Rules,17,"popularity").State);b.Simulation.Execute("start_business");while(b.Simulation.State.phase!="closed")b.Simulation.Execute("advance_business");b.Simulation.Execute("advance_goal");b.Simulation.Execute("next_day");Check(b.Simulation.State.visiting_cat.status=="visiting","appearance");}
  static LocalCafeBackend Reload(LocalCafeBackend b,string folder,int slot){Good(b,"save_game",slot:slot);var fresh=new LocalCafeBackend(folder,b.Simulation.Rules);Good(fresh,"load_game",slot:slot);return fresh;}
  public static int Run(string root){checks=0;Directory.CreateDirectory(root);string folder=Path.Combine(root,Guid.NewGuid().ToString("N"));var b=new LocalCafeBackend(folder,Rules());Check(b.CocoConversation==null,"before appearance conversation");b=Reload(b,folder,1);Setup(b);
   Check(b.CocoConversation.progress.branch_id=="meeting" && !b.ConversationBlocksProgress,"optional meeting blocks");var facts=Facts(b);b.CocoConversation.progress.node=1;b.CocoConversation.progress.page_offset=2;b=Reload(b,folder,2);Check(b.CocoConversation.progress.node==1 && b.CocoConversation.progress.page_offset==2 && Facts(b)==facts,"meeting resume");Check(!b.Replays.Load().entries.Any(e=>e.conversation_id==CafeCocoDialogue.MeetingId),"unread Extra");Good(b,"day_off");Check(b.CocoConversation.progress.node==1,"optional meeting lost on day off");Finish(b);Check(b.Replays.Load().entries.Any(e=>e.conversation_id==CafeCocoDialogue.MeetingId),"meeting Extra");
   Good(b,"resolve_visiting_cat","skip");Check(b.Simulation.VisitingProgress==0,"skip progress");Check(Send(b,"resolve_visiting_cat","interact").result!=UnityWebRequest.Result.Success,"daily duplicate");Good(b,"day_off");
   for(int i=1;i<=3;i++){Good(b,"resolve_visiting_cat","interact");Check(b.Simulation.VisitingProgress==i,"daily count");if(i==1)b=Reload(b,folder,4);if(i<3)Good(b,"day_off");}
   Check(b.CocoConversation.progress.branch_id=="introduction" && b.View().visiting_cat.can_accept,"immediate admission");facts=Facts(b);b.CocoLater();Check(Facts(b)==facts && b.CocoConversation.progress.branch_id=="later" && !b.ConversationBlocksProgress,"later changes gameplay");Finish(b);Check(b.Replays.Load().entries.Count(e=>e.conversation_id==CafeCocoDialogue.AdmissionId)==1,"later Extra");b.PrepareCocoConversation(true);Check(b.CocoConversation.attempt==2,"repeat absent");b.CocoLater();Finish(b);Check(b.Replays.Load().entries.Count(e=>e.conversation_id==CafeCocoDialogue.AdmissionId)==1,"repeat duplicated Extra");b.PrepareCocoConversation(true);
   var p=b.CocoConversation.progress;p.node=1;p.page_offset=2;b=Reload(b,folder,3);Check(b.CocoConversation.progress.node==1 && b.CocoConversation.progress.page_offset==2,"admission intro resume");
   double funds=b.Simulation.State.funds;foreach(double amount in new[]{199d,200d,201d}){b.Simulation.State.funds=amount;Check(b.View().visiting_cat.can_accept==(amount>200),"fund boundary");if(amount<=200){string before=Facts(b);Check(Send(b,"resolve_visiting_cat","accept").result!=UnityWebRequest.Result.Success && Facts(b)==before,"insufficient funds mutated");}}b.Simulation.State.funds=funds;int capacity=b.Simulation.Rules.housing.initial_capacity;b.Simulation.Rules.housing.initial_capacity=b.Simulation.ActiveCatCount(b.Simulation.State);Check(!b.View().visiting_cat.can_accept && !b.ConversationBlocksProgress,"full blocks closing");Check(Send(b,"resolve_visiting_cat","accept").result!=UnityWebRequest.Result.Success,"full admission allowed");b.Simulation.Rules.housing.initial_capacity=capacity;
   Good(b,"resolve_visiting_cat","accept");Check(b.CocoConversation.progress.branch_id=="accepted" && b.Simulation.State.funds==funds-200 && b.Simulation.State.recruitment_expenses==200,"accept once");facts=Facts(b);Check(Send(b,"resolve_visiting_cat","accept").result!=UnityWebRequest.Result.Success && Facts(b)==facts,"double admission");b.CocoConversation.progress.node=1;b.CocoConversation.progress.page_offset=3;b=Reload(b,folder,9);Check(b.CocoConversation.progress.branch_id=="accepted" && b.CocoConversation.progress.node==1 && b.CocoConversation.progress.page_offset==3 && Facts(b)==facts,"result restart");File.Copy(Path.Combine(folder,"slot-9.json"),Path.Combine(root,"result-save.json"),true);Finish(b);Check(b.Replays.Load().entries.Count(e=>e.conversation_id==CafeCocoDialogue.AdmissionId)==2 && Facts(b)==facts,"accepted Extra / replay mutates");b.PrepareCocoConversation(true);Check(b.CocoConversation==null,"accepted creates new meeting");
   foreach(int slot in new[]{1,2,4,3,9}){string oldFolder=Path.Combine(root,"legacy-"+slot+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(oldFolder);var old=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(folder,"slot-"+slot+".json")));old.coco_conversations=null;old.slot=1;File.WriteAllText(Path.Combine(oldFolder,"slot-1.json"),JsonUtility.ToJson(old));var legacy=new LocalCafeBackend(oldFolder,Rules());Good(legacy,"load_game");Check(!legacy.CocoConversations.Any(r=>r.progress.completed),"legacy invented viewed");Check(slot==1 || slot==9?legacy.CocoConversation==null:legacy.CocoConversation.progress.branch_id=="meeting","legacy status");}
   return checks;
  }
  string output;LocalCafeBackend backend;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--catcafe-coco-adv-check");if(i<0)return;var q=new GameObject("Coco ADV QA").AddComponent<StandaloneCocoConversationSmoke>();DontDestroyOnLoad(q);q.output=Path.GetFullPath(a[i+1]);Directory.CreateDirectory(q.output);Application.runInBackground=true;q.StartCoroutine(q.Guard());}
  System.Collections.IEnumerator Guard(){var run=Player();while(true){object next;try{if(!run.MoveNext())yield break;next=run.Current;}catch(Exception ex){File.WriteAllText(Path.Combine(output,"failure.txt"),ex.ToString());throw;}yield return next;}}
  static void Apply(PythonStateClient c)=>typeof(PythonStateClient).GetMethod("Accept",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(c,new object[]{(CafeBackends.Local as LocalCafeBackend).View()});
  System.Collections.IEnumerator Player(){yield return new WaitForSecondsRealtime(1);Run(Path.Combine(output,"backend"));bool restart=Environment.GetCommandLineArgs().Contains("--coco-resume");backend=new LocalCafeBackend(Path.Combine(output,"manual"),Rules());if(restart)Good(backend,"load_game",slot:9);else Setup(backend);CafeBackends.UseLocal(backend);UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);var c=FindObjectOfType<PythonStateClient>();Apply(c);yield return null;var ui=c.GetComponent<CocoConversationPanel>();Check(ui!=null && ui.Showing,"UI absent");
   if(!restart){string facts=Facts(backend);ui.Next();int once=backend.CocoConversation.progress.node;ui.Next();Check(backend.CocoConversation.progress.node==once,"double next in one frame");yield return null;Check(Facts(backend)==facts,"rapid click changes gameplay");Good(backend,"save_game",slot:8);backend.ConversationOpen=true;Apply(c);yield return null;Check(!ui.Showing,"overlaps another conversation");backend.ConversationOpen=false;Apply(c);yield return null;Check(ui.Showing,"optional conversation not restored");
    Finish(backend);for(int i=1;i<=3;i++){Good(backend,"resolve_visiting_cat","interact");if(i<3)Good(backend,"day_off");}backend.CocoConversation.progress.node=3;Apply(c);yield return null;Check(ui.Showing,"ready UI absent");ui.Close();c.GetComponent<PythonEventListPanel>().Open();c.GetComponent<PythonEventListPanel>().Visiting();yield return null;Check(ui.Showing && !c.GetComponent<PythonEventListPanel>().panel.activeSelf && !c.GetComponent<PythonVisitingCatPanel>().panel.activeSelf,"list overlays ADV");
    var accept=ui.GetComponentsInChildren<UnityEngine.UI.Button>().First(b=>b.GetComponentInChildren<UnityEngine.UI.Text>().text=="迎える");accept.onClick.Invoke();yield return null;var cancel=ui.GetComponentsInChildren<UnityEngine.UI.Button>().First(b=>b.GetComponentInChildren<UnityEngine.UI.Text>().text=="取消");cancel.onClick.Invoke();Check(backend.Simulation.State.visiting_cat.status=="ready","cancel accepted");

    backend.CocoLater();Apply(c);yield return null;string beforeLater=Facts(backend);for(int n=0;n<30 && ui.Showing;n++){ui.Next();yield return null;}Check(Facts(backend)==beforeLater && c.GetComponent<PythonVisitingCatPanel>().panel.activeSelf,"later reading / daily return");
    ui.OpenPending(true);backend.CocoConversation.progress.node=3;Apply(c);yield return null;
    Good(backend,"save_game",slot:7);Good(backend,"resolve_visiting_cat","accept");backend.CocoConversation.progress.node=1;Good(backend,"save_game",slot:9);

    Finish(backend);string beforeExtra=Facts(backend),meta=JsonUtility.ToJson(new CafeSaveEnvelope{coco_conversations=backend.CocoConversations});
    UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafeTitle");yield return new WaitForSecondsRealtime(2);var extra=FindObjectOfType<PythonTitleScreen>().GetComponent<TitleExtraPanel>();extra.Open();yield return null;
    foreach(string key in new[]{CafeCocoDialogue.MeetingId+"/meeting",CafeCocoDialogue.AdmissionId+"/later",CafeCocoDialogue.AdmissionId+"/accepted"}){extra.OpenReplay(key);yield return null;Check(extra.Replay.Showing,"Extra UI absent "+key);for(int n=0;n<60 && extra.Replay.Showing;n++){extra.Replay.Next();yield return null;}extra.Replay.Close();}
    Check(Facts(backend)==beforeExtra && JsonUtility.ToJson(new CafeSaveEnvelope{coco_conversations=backend.CocoConversations})==meta,"Extra changes state");extra.Hide();Good(backend,"load_game",slot:9);UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);c=FindObjectOfType<PythonStateClient>();Apply(c);yield return null;ui=c.GetComponent<CocoConversationPanel>();
   }else Check(backend.CocoConversation.progress.branch_id=="accepted" && backend.CocoConversation.progress.node==1,"separate process result resume");
   Screen.SetResolution(restart?1024:1280,restart?768:800,false);Apply(c);yield return null;File.WriteAllText(Path.Combine(output,restart?"restart-result.txt":"result.txt"),"PASS: "+checks);
  }
 }
}
